const body = $json.body ?? $json;
if (!body.ticket_id || !body.subject) { throw new Error('ticket_id and subject are required'); }
return [{ json: { ticket_id: body.ticket_id, subject: body.subject, priority: body.priority ?? 'Medium', customer: body.customer ?? 'Unknown', received_at: new Date().toISOString() } }];
